"""Render an atlas snapshot into a self-contained offline HTML document."""

from __future__ import annotations

import html
import json
from pathlib import Path


def render(snapshot: dict) -> str:
    # Keep untrusted metadata inside the JSON literal, including </script>.
    payload = json.dumps(snapshot, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    library = (Path(__file__).resolve().parents[1] / "assets" / "hierarchy.umd.js").read_text(encoding="utf-8")
    return TEMPLATE.replace("__ATLAS_JSON__", payload).replace("__HIERARCHY_LIB__", library)


def write_html(snapshot: dict, output: Path) -> Path:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render(snapshot), encoding="utf-8")
    return output


TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>技能地图</title><link rel="icon" href="data:,"><!-- Interactive skill map --><style>
:root{color-scheme:dark;--bg:#0b1014;--panel:#121a20;--panel2:#17232b;--line:#2a3b43;--ink:#e9f0ef;--muted:#8ea1a5;--accent:#53d6b4;--warn:#f4bd67;--bad:#ff7b88}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% -20%,#183b3b 0,#0b1014 38%);color:var(--ink);font:14px/1.45 ui-monospace,SFMono-Regular,Menlo,monospace;min-height:100vh}header{padding:26px 32px 20px;border-bottom:1px solid var(--line);display:flex;align-items:end;justify-content:space-between;gap:24px}h1{margin:0;font-size:24px;letter-spacing:0}header p{margin:5px 0 0;color:var(--muted)}.stats{display:flex;gap:16px;color:var(--muted);font-size:12px}.stats strong{display:block;color:var(--accent);font-size:20px}.toolbar{display:flex;gap:10px;padding:16px 32px;border-bottom:1px solid var(--line);flex-wrap:wrap}.toolbar input,.toolbar select,.toolbar button{background:var(--panel);border:1px solid var(--line);color:var(--ink);padding:9px 11px;border-radius:4px;font:inherit}.toolbar input{min-width:260px;flex:1}.toolbar button{cursor:pointer}.toolbar button:hover,.toolbar button:focus-visible{border-color:var(--accent);outline:none}.layout{display:grid;grid-template-columns:270px minmax(0,1fr) 310px;min-height:calc(100vh - 145px)}aside,.details{padding:22px;border-right:1px solid var(--line);background:rgba(18,26,32,.74)}.details{border-left:1px solid var(--line);border-right:0}.panel-title{color:var(--muted);font-size:11px;letter-spacing:.12em;margin-bottom:14px}.category{display:flex;align-items:center;justify-content:space-between;width:100%;padding:8px 0;background:none;border:0;color:var(--ink);font:inherit;text-align:left;cursor:pointer}.category span:last-child{color:var(--muted);font-size:12px}.category.active{color:var(--accent);border-left:2px solid var(--accent);padding-left:8px}.category[aria-expanded="false"]{color:var(--muted)}.legend{margin-top:28px;color:var(--muted);font-size:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:7px;background:var(--accent)}.dot.warn{background:var(--warn)}main{position:relative;overflow:hidden;background:linear-gradient(transparent 95%,rgba(83,214,180,.04)),repeating-linear-gradient(0deg,transparent,transparent 39px,rgba(130,170,170,.04) 40px),repeating-linear-gradient(90deg,transparent,transparent 39px,rgba(130,170,170,.04) 40px)}#canvas{width:100%;height:100%;min-height:520px;display:block;cursor:grab}#canvas.dragging{cursor:grabbing}.edge{stroke:#3e5d61;stroke-width:1.2;opacity:.7}.node{cursor:pointer}.node circle{fill:var(--panel2);stroke:#63898b;stroke-width:1.3}.node.center-node circle{fill:#315b78;stroke:#fff;stroke-width:2.4}.node.category-node circle{fill:#183f3d;stroke:var(--accent);stroke-width:1.8}.node.skill-node text{font-size:10px}.node text{fill:var(--ink);font-size:11px;pointer-events:none}.node.category-node text{font-weight:700}.node.selected circle{stroke:#fff;stroke-width:2.5}.empty{padding:55px;color:var(--muted);text-align:center}.details h2{font-size:18px;margin:0 0 8px;overflow-wrap:anywhere}.details p{color:var(--muted);margin:8px 0}.tag{display:inline-block;border:1px solid var(--line);color:var(--accent);padding:3px 6px;margin:3px 4px 3px 0;font-size:11px;border-radius:3px}.warning{color:var(--warn);border-left:2px solid var(--warn);padding-left:10px}.close{float:right;background:none;border:0;color:var(--muted);font-size:20px;cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px){header{padding:20px;align-items:start;flex-direction:column}.toolbar{padding:12px 20px}.layout{display:block}.layout aside{border:0;border-bottom:1px solid var(--line);padding:16px 20px}.layout main{height:58vh;min-height:390px}.details{position:fixed;z-index:3;right:0;top:0;bottom:0;width:min(92vw,360px);transform:translateX(100%);transition:transform .2s ease;border-left:1px solid var(--line);box-shadow:-16px 0 40px #0008}.details.open{transform:translateX(0)}#canvas{min-height:390px}}
</style></head><body><header><div><h1>技能地图 <span id="host"></span></h1><p id="subtitle">当前终端的本地技能清单</p></div><div class="stats"><div><strong id="skillCount">0</strong>个技能</div><div><strong id="categoryCount">0</strong>个分类</div><div><strong id="warningCount">0</strong>条警告</div></div></header><div class="toolbar"><label class="sr-only" for="search">搜索技能</label><input id="search" placeholder="搜索技能名称、摘要或触发词..." autocomplete="off"><label class="sr-only" for="status">筛选状态</label><select id="status"><option value="all">全部状态</option><option value="valid">有效</option><option value="warning">有警告</option><option value="invalid">无效</option></select><label class="sr-only" for="level">筛选层级</label><select id="level"><option value="all">全部层级</option><option value="1">一级</option><option value="2">二级</option><option value="3">三级</option></select><button id="reset" type="button">重置视图</button></div><div class="layout"><aside><div class="panel-title">分类列表</div><div id="categories"></div><div class="legend"><div><span class="dot"></span>有效技能</div><div><span class="dot warn"></span>解析警告</div><p>点击分类展开或收起；点击节点查看详细说明。</p></div></aside><main><svg id="canvas" role="img" aria-label="交互式技能脑图"></svg><div id="empty" class="empty" hidden>当前筛选条件下没有技能。</div></main><section id="details" class="details" aria-live="polite"><button id="close" class="close" type="button" aria-label="关闭详情">&times;</button><div class="panel-title">详细说明</div><div id="detailBody"><p>请选择一个分类或技能节点。</p></div></section></div><script>
const DATA=__ATLAS_JSON__;__HIERARCHY_LIB__
const glowStyle=document.createElement('style');glowStyle.textContent='.node circle,.node.category-node rect{filter:drop-shadow(0 0 7px #53d6b488)}.node.category-node rect{fill:#123f43;stroke:#53d6b4;stroke-width:1.8}.node.center-node circle{fill:#246b83;filter:drop-shadow(0 0 16px #69d7ffaa)}.edge{stroke:#53d6b466;stroke-width:1.6;stroke-dasharray:4 5}.node.skill-node text{font-size:12px;font-weight:600}.node text{paint-order:stroke;stroke:#0b1014;stroke-width:4px;stroke-linejoin:round}';document.head.appendChild(glowStyle);
const $=id=>document.getElementById(id);let state={query:'',status:'all',level:'all',collapsed:new Set(),selected:null,activeCategory:null,zoom:1,pan:{x:0,y:0},drag:null};
function filtered(){const q=state.query.toLowerCase();return DATA.skills.filter(s=>(state.status==='all'||s.status===state.status)&&(state.level==='all'||String(s.level)===state.level)&&(!q||[s.name,s.display_name,s.description,s.summary,...s.triggers,...s.headings].join(' ').toLowerCase().includes(q)))}
function groups(skills){const out={};skills.forEach(s=>{const p=s.category||'其他能力',c=s.parent_category||'';(out[p]??={});(out[p][c]??=[]).push(s)});return out}
function renderSidebar(list){const g=groups(list);let h='';Object.entries(g).sort().forEach(([p,ch])=>{const pk='p:'+p,open=!state.collapsed.has(pk),all=Object.values(ch).flat(),children=Object.entries(ch).filter(([c])=>c),marker=children.length?(open?'▾':'▸')+' ':'';h+=`<button class="category ${state.activeCategory===p?'active':''}" ${children.length?`aria-expanded="${open}"`:''} data-category="${esc(pk)}"><span>${marker}${esc(p)}</span><span>${all.length}</span></button>`;if(open)children.sort().forEach(([c,m])=>{const k=p+'::'+c;h+=`<button class="category child ${state.activeCategory===k?'active':''}" aria-expanded="${!state.collapsed.has(k)}" data-category="${esc(k)}"><span>　${state.collapsed.has(k)?'▸':'▾'} ${esc(c)}</span><span>${m.length}</span></button>`})});$('categories').innerHTML=h;$('categories').querySelectorAll('.category').forEach(b=>b.onclick=()=>{const k=b.dataset.category;state.activeCategory=k;state.collapsed.has(k)?state.collapsed.delete(k):state.collapsed.add(k);draw(filtered())})}
function esc(v){return String(v).replace(/\s*\/\s*/g,' · ').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function layout(list){
 const grouped=groups(list),categoryNames=Object.keys(grouped).sort(),positions={center:{x:1050,y:520}};
 const lanes=[categoryNames.filter((_,i)=>i%2===0),categoryNames.filter((_,i)=>i%2===1)];
 lanes.forEach((cats,side)=>{let y=80;const dir=side===0?-1:1;cats.forEach(cat=>{const children=Object.keys(grouped[cat]).filter(Boolean), direct=grouped[cat]['']||[];let branch=Math.max(children.length*90,direct.length*58,110);const cy=y+branch/2-20;positions['cat:'+cat]={x:1050+dir*300,y:cy};children.forEach(child=>{const members=grouped[cat][child],subY=y;positions['sub:'+cat+'::'+child]={x:1050+dir*600,y:subY+20};members.forEach((s,i)=>{positions[s.id]={x:1050+dir*900,y:subY+20+i*58}});y+=Math.max(100,members.length*58+35)});direct.forEach((s,i)=>{positions[s.id]={x:1050+dir*600,y:y+20+i*58}});y+=Math.max(branch, direct.length*58)+50})});
 const width=2200,height=Math.max(700,Math.max(...Object.values(positions).map(p=>p.y))+140);
 document.querySelector('main').style.overflow='auto';
 $('canvas').style.width=width+'px';$('canvas').style.height=height+'px';
 return {positions,width,height};
}
function draw(list){$('skillCount').textContent=list.length;$('categoryCount').textContent=new Set(list.map(s=>s.category)).size;$('warningCount').textContent=DATA.warnings.length+list.filter(s=>s.warnings.length).length;$('host').textContent=`· ${esc(DATA.host)}`;renderSidebar(list);const svg=$('canvas');svg.innerHTML='';$('empty').hidden=list.length>0;if(!list.length)return;const {positions,width,height}=layout(list);svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('transform',`translate(${state.pan.x} ${state.pan.y}) scale(${state.zoom})`);const grouped=groups(list),cats=Object.keys(grouped);const edge=(a,b)=>{if(!a||!b)return;const l=document.createElementNS(svg.namespaceURI,'line');l.setAttribute('x1',a.x);l.setAttribute('y1',a.y);l.setAttribute('x2',b.x);l.setAttribute('y2',b.y);l.setAttribute('class','edge');g.appendChild(l)};cats.forEach(cat=>{const cp=positions['cat:'+cat];edge(positions.center,cp);Object.entries(grouped[cat]).forEach(([child,members])=>{if(!child){if(!state.collapsed.has('p:'+cat))members.forEach(s=>edge(cp,positions[s.id]));return}const sp=positions['sub:'+cat+'::'+child];edge(cp,sp);if(state.collapsed.has(cat+'::'+child))return;members.forEach(s=>edge(sp,positions[s.id]))})});cats.forEach(cat=>{const p=positions['cat:'+cat];node(g,'cat:'+cat,p.x,p.y,cat,22,true,()=>{const k='p:'+cat;state.collapsed.has(k)?state.collapsed.delete(k):state.collapsed.add(k);draw(filtered())});Object.entries(grouped[cat]).forEach(([child])=>{if(!child)return;const id='sub:'+cat+'::'+child,q=positions[id];node(g,id,q.x,q.y,child,18,true,()=>{const k=cat+'::'+child;state.collapsed.has(k)?state.collapsed.delete(k):state.collapsed.add(k);draw(filtered())})})});node(g,'center',positions.center.x,positions.center.y,DATA.host,34,true,()=>{});list.forEach(s=>{if(state.collapsed.has('p:'+s.category)||state.collapsed.has(s.category+'::'+s.parent_category))return;const p=positions[s.id];if(!p)return;node(g,s.id,p.x,p.y,s.name,10,false,()=>select(s))});svg.appendChild(g)}
function node(parent,id,x,y,label,radius,isCat,click){const ns='http://www.w3.org/2000/svg';const group=document.createElementNS(ns,'g');group.setAttribute('class',`node ${isCat?(id==='center'?'center-node ':'category-node '):'skill-node '}${state.selected===id?'selected':''}`);group.setAttribute('tabindex','0');group.setAttribute('role','button');group.setAttribute('aria-label',label);group.addEventListener('click',click);group.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();click()}});const shape=isCat&&id==='center'?document.createElementNS(ns,'circle'):document.createElementNS(ns,'rect');if(shape.tagName==='circle'){shape.setAttribute('cx',x);shape.setAttribute('cy',y);shape.setAttribute('r',radius)}else{shape.setAttribute('x',x-110);shape.setAttribute('y',y-22);shape.setAttribute('width',220);shape.setAttribute('height',44);shape.setAttribute('rx',10)}group.appendChild(shape);const text=document.createElementNS(ns,'text');text.setAttribute('x',x);text.setAttribute('y',y+5);text.setAttribute('text-anchor','middle');text.textContent=label.length>28?label.slice(0,27)+'…':label;group.appendChild(text);parent.appendChild(group)}
function selectCategory(name,members){state.selected='cat:'+name;const d=$('detailBody');d.innerHTML=`<h2>${esc(name)}</h2><p>此分类包含 ${members.length} 个技能。</p><p>${members.slice(0,12).map(s=>`<span class="tag">${esc(s.name)}</span>`).join('')}</p>`;$('details').classList.add('open');draw(filtered())}
function chineseExplanation(skill){return skill.summary||'该 Skill 未提供可生成中文总结的说明。'}
function select(skill){state.selected=skill.id;const d=$('detailBody');d.innerHTML=`<h2>${esc(skill.name)}</h2><p><strong>触发词：</strong>${skill.triggers.length?skill.triggers.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):'暂无'}</p><p><strong>详细说明：</strong>${esc(chineseExplanation(skill))}</p><p><strong>路径：</strong><br>${esc(skill.path)}</p>`;$('details').classList.add('open');draw(filtered())}
$('search').oninput=e=>{state.query=e.target.value;draw(filtered())};$('status').onchange=e=>{state.status=e.target.value;draw(filtered())};$('level').onchange=e=>{state.level=e.target.value;draw(filtered())};$('reset').onclick=()=>{state={...state,query:'',status:'all',level:'all',collapsed:new Set(),selected:null,zoom:1,pan:{x:0,y:0}};$('search').value='';$('status').value='all';$('level').value='all';$('details').classList.remove('open');draw(filtered())};$('close').onclick=()=>$('details').classList.remove('open');$('canvas').addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.55,Math.min(2.2,state.zoom*(e.deltaY<0?1.1:.9)));draw(filtered())},{passive:false});$('canvas').addEventListener('pointerdown',e=>{if(e.target.closest('.node'))return;state.drag={x:e.clientX,y:e.clientY,pan:{...state.pan}};$('canvas').classList.add('dragging');$('canvas').setPointerCapture(e.pointerId)});$('canvas').addEventListener('pointermove',e=>{if(!state.drag)return;state.pan.x=state.drag.pan.x+e.clientX-state.drag.x;state.pan.y=state.drag.pan.y+e.clientY-state.drag.y;draw(filtered())});$('canvas').addEventListener('pointerup',e=>{state.drag=null;$('canvas').classList.remove('dragging');$('canvas').releasePointerCapture(e.pointerId)});window.addEventListener('resize',()=>draw(filtered()));draw(filtered());
</script></body></html>'''
